public class MainView extends AppLayout {

    private UnorderedList itemsList;
    private Span countSpan;
    private TextField itemField;

    public MainView() {
        H2 appTitle = new H2("Item Tracker");
        addToNavbar(appTitle);

        VerticalLayout content = new VerticalLayout();

        H1 heading = new H1("Items");
        content.add(heading);

        itemField = new TextField("Item");
        itemField.setEmptyValue("");
        content.add(itemField);

        itemsList = new UnorderedList();
        content.add(itemsList);

        countSpan = new Span("Items: 0");
        content.add(countSpan);

        Button addButton = new Button("Add", event -> addItem());
        Button clearButton = new Button("Clear", event -> clearItems());
        content.add(addButton, clearButton);

        setContent(content);
    }

    private void addItem() {
        String value = itemField.getValue().trim();
        if (value.isEmpty()) {
            itemField.setInvalid(true);
            return;
        }

        itemField.setInvalid(false);
        ListItem item = new ListItem(value);
        itemsList.add(item);
        itemField.setValue("");
        updateCount();
    }

    private void clearItems() {
        itemsList.removeAll();
        updateCount();
    }

    private void updateCount() {
        int count = (int) itemsList.getChildren().count();
        countSpan.setText("Items: " + count);
    }
